function drawDratiniAzureDragon(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const finFlutter = Math.sin(t * 4.0) * 3.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(-4, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Thân rồng uốn lượn
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.ellipse(-16, by + 26, 12, 7, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-28, by + 24); ctx.lineTo(-38, by + 18); ctx.lineTo(-22, by + 28); ctx.fill();

  ctx.beginPath(); ctx.roundRect(4, by + 6, 12, 22, 5); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.roundRect(6, by + 8, 8, 20, 4); ctx.fill();

  // 3. Đầu rồng
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.arc(10, by - 10, 16 * sX, 0, Math.PI * 2); ctx.fill();

  // 4. Mũi trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(2, by - 6, 8, 0, Math.PI * 2); ctx.fill();

  // 5. Ngọc trán
  ctx.beginPath(); ctx.arc(10, by - 22, 4, 0, Math.PI * 2); ctx.fill();

  // 6. Cánh tai
  ctx.beginPath(); ctx.moveTo(-2, by - 16); ctx.lineTo(-18 + finFlutter, by - 28); ctx.lineTo(2, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(20, by - 20); ctx.lineTo(32 - finFlutter, by - 34); ctx.lineTo(24, by - 14); ctx.fill();

  // 7. Má hồng
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(4, by - 2, 3, 0, Math.PI * 2); ctx.fill();

  // 8. Mắt tím
  if (!blink) {
    ctx.fillStyle = '#7c3aed';
    ctx.beginPath(); ctx.ellipse(10, by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(9,  by - 13, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(11, by - 7,  1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.ellipse(10, by - 10, 4, 2, 0, 0, Math.PI * 2); ctx.stroke();
  }

  ctx.restore();
}
